import json

def get_weather(city):
    return {"city": city, "temp_c": 31}

def add(a, b):
    return a + b

TOOLS = {"get_weather": get_weather, "add": add}

REPLIES = [
    '{"tool": "get_weather", "args": {"city": "Perth"}}',
    '{"tool": "add", "args": {"a": 2, "c": 3}}',
    '{"tool": "search", "args": {"q": "dns"}}',
    '{"tool": "add", "args": {"a": 2, "b": 3}}',
    '{"final": "Perth is 31C and 2 + 3 = 5"}',
]

def call_model(messages):
    turns_so_far = sum(1 for m in messages if m["role"] == "assistant")
    return REPLIES[turns_so_far]

def run(task, max_turns=4):
    messages = [{"role": "user", "content": task}]
    for turn in range(1, max_turns + 1):
        reply = json.loads(call_model(messages))
        messages.append({"role": "assistant", "content": reply})
        if "final" in reply:
            return f"done in {turn}: {reply['final']}"
        fn = TOOLS.get(reply["tool"])
        if fn is None:
            result = {"error": f"unknown tool {reply['tool']}"}
        else:
            try:
                result = fn(**reply["args"])
            except TypeError as e:
                result = {"error": str(e)}
        print(turn, reply["tool"], "->", result)
        messages.append({"role": "tool", "content": result})
    return f"stopped: turn cap {max_turns}"

print(run("weather and sum"))
print(run("weather and sum", max_turns=5))
